package mage.player.ai;
import mage.Mana;import mage.abilities.*;import mage.abilities.keyword.BestowAbility;import mage.cards.Card;import mage.constants.*;import mage.game.permanent.*;import mage.game.turn.*;import java.util.*;
import static mage.player.ai.FourthSeatRealGameTest.check;import static mage.player.ai.RecoveryChecks.*;
public final class FourthSeatRecoveredGrowthTest {
 static FourthSeatRealGameTest.Fixture army(int count,boolean tapped,boolean projected,boolean blue,int lands,int hand)throws Exception{FourthSeatRealGameTest.Fixture f=new FourthSeatRealGameTest.Fixture();f.game.initializeRollbackOrder();Permanent a=f.board("a.AesiTyrantOfGyreStrait","Aesi, Tyrant of Gyre Strait");f.identifyCommander(a.getId());a.setTapped(true);for(int i=0;i<count;i++){Card c=f.card("s.ScuteSwarm","Scute Swarm");PermanentCard p=new PermanentCard(c,f.bot.getId(),f.game);f.game.addPermanent(p,0);f.game.getState().setZone(c.getId(),Zone.BATTLEFIELD);p.setTapped(tapped);}for(int i=0;i<lands;i++){boolean island=blue&&i%3==0;Permanent p=f.board(island?"basiclands.Island":"basiclands.Forest",island?"Island":"Forest");p.setTapped(projected);}for(int i=0;i<hand;i++)f.hand("g.GrowthSpiral","Growth Spiral");return f;}
 static List<Permanent> scutes(FourthSeatRealGameTest.Fixture f){List<Permanent> out=new ArrayList<>();for(Permanent p:f.game.getBattlefield().getAllActivePermanents(f.bot.getId()))if(p.getName().equals("Scute Swarm"))out.add(p);return out;}
 static boolean reserve(FourthSeatRealGameTest.Fixture f)throws Exception{return flag(f,"reserveGrowthSaturated");}
 static void shrink(FourthSeatRealGameTest.Fixture f){f.bot.getHand().getCards(f.game).iterator().next().moveToZone(Zone.GRAVEYARD,null,f.game,false);}
 static void post(FourthSeatRealGameTest.Fixture f){PostCombatMainPhase p=new PostCombatMainPhase();p.setStep(new PostCombatMainStep());f.game.getTurn().setPhase(p);}
 public static void main(String[]args)throws Exception{
  for(boolean projected:new boolean[]{false,true})run("Fresh32 future reserve projected="+projected,()->{FourthSeatRealGameTest.Fixture f=army(32,false,projected,true,8,5);check(reserve(f),"Initial reserve absent");check(!flag(f,"combatBeforeDevelopment"),"Sick army represented as combat ready");check(flag(f,"reserveUsesProjectedMana")==projected,"Projection not distinguished");check(!f.bot.priority(f.game)&&f.bot.getHand().size()==5,"Redundant growth cast");});
  for(String condition:new String[]{"31","tapped","short-hand","missing-blue","short-mana"})run("Initial Scute proof rejects "+condition,()->{FourthSeatRealGameTest.Fixture f=army(condition.equals("31")?31:32,condition.equals("tapped"),false,!condition.equals("missing-blue"),condition.equals("short-mana")?2:8,condition.equals("short-hand")?4:5);check(!reserve(f),"Invalid initial proof");});
  run("Real useful cast preserves same-turn hand5 to4 proof",()->{FourthSeatRealGameTest.Fixture f=army(32,false,false,true,8,4);Card c=f.hand("l.LightningGreaves","Lightning Greaves");check(reserve(f),"Initial proof absent");check(f.bot.activateAbility(c.getSpellAbility(),f.game),"Greaves cast failed");drain(f,10);check(f.bot.getHand().size()==4&&reserve(f),"Useful cast revoked prior proof");});
  run("Actual attack commitment holds postcombat Myriad",()->{FourthSeatRealGameTest.Fixture f=army(32,false,false,true,8,5);Permanent m=f.board("m.MyriadLandscape","Myriad Landscape");check(reserve(f),"Initial proof absent");for(Permanent p:scutes(f))((PermanentCard)p).removeSummoningSickness();f.combat();f.bot.selectAttackers(f.game,f.bot.getId());check(f.game.getCombat().getAttackers().size()>=32,"Actual army not committed");check(reserve(f),"Attack commitment not observed");post(f);shrink(f);check(reserve(f),"Postcombat proof lost");f.bot.priority(f.game);check(f.game.getPermanent(m.getId())!=null&&f.game.getStack().isEmpty(),"Myriad expanded growth after combat");});
  for(String cause:new String[]{"turn","offturn","count","wipe","resources","arbitrary-tap"})run("Prior proof invalidation "+cause,()->{FourthSeatRealGameTest.Fixture f=army(32,false,false,true,8,5);check(reserve(f),"Initial proof absent");shrink(f);if(cause.equals("turn"))f.game.getState().setTurnNum(f.game.getState().getTurnNum()+1);if(cause.equals("offturn"))f.game.getState().setActivePlayerId(f.foes[0].getId());if(cause.equals("count"))scutes(f).get(0).moveToZone(Zone.GRAVEYARD,null,f.game,false);if(cause.equals("wipe"))for(Permanent p:scutes(f))p.moveToZone(Zone.GRAVEYARD,null,f.game,false);if(cause.equals("resources"))for(Permanent p:new ArrayList<>(f.game.getBattlefield().getAllActivePermanents(f.bot.getId())))if(p.isLand(f.game))p.moveToZone(Zone.GRAVEYARD,null,f.game,false);if(cause.equals("arbitrary-tap"))for(Permanent p:scutes(f))p.setTapped(true);f.game.applyEffects();check(!reserve(f),"Stale proof survived");if(cause.equals("arbitrary-tap")){for(Permanent p:scutes(f))p.setTapped(false);check(!reserve(f),"Invalidated proof resurrected without initial hand threshold");}});
  run("Copied proof still rechecks live resources",()->{FourthSeatRealGameTest.Fixture f=army(32,false,false,true,8,5);check(reserve(f),"Initial proof absent");shrink(f);ComputerPlayerFourthSeat copy=f.bot.copy();check(copy.observe(f.game).getClass().getField("reserveGrowthSaturated").getBoolean(copy.observe(f.game)),"Copy lost proof");for(Permanent p:new ArrayList<>(f.game.getBattlefield().getAllActivePermanents(f.bot.getId())))if(p.isLand(f.game))p.moveToZone(Zone.GRAVEYARD,null,f.game,false);check(!copy.observe(f.game).getClass().getField("reserveGrowthSaturated").getBoolean(copy.observe(f.game)),"Copy skipped live resource check");});
  run("Pending opponent stack cannot reopen Harrow growth",()->{FourthSeatRealGameTest.Fixture f=army(81,false,false,true,8,5);f.board("t.TravelingChocobo","Traveling Chocobo");Card harrow=f.hand("h.Harrow","Harrow");Card shock=f.enemyHand("s.Shock","Shock");shock.getSpellAbility().getTargets().get(0).addTarget(f.foes[1].getId(),shock.getSpellAbility(),f.game);f.castEnemy(shock);check(reserve(f),"Pending stack or typed land-sacrifice erased reserve");f.bot.priority(f.game);check(f.bot.getHand().contains(harrow.getId())&&f.game.getStack().size()==1,"Harrow expanded pending chain");});
  for(boolean ashaya:new boolean[]{false,true})run("Ashaya creature development hold only with validated Scute reserve="+ashaya,()->{FourthSeatRealGameTest.Fixture f=army(32,false,false,true,8,5);if(ashaya)f.board("a.AshayaSoulOfTheWild","Ashaya, Soul of the Wild");Card bear=f.hand("g.GrizzlyBears","Grizzly Bears");check(reserve(f),"Reserve absent");f.bot.priority(f.game);check(f.game.getState().getZone(bear.getId())==(ashaya?Zone.HAND:Zone.STACK),"Wrong Ashaya development boundary");});
  run("Reserve preserves actual protection",()->{FourthSeatRealGameTest.Fixture f=army(32,false,false,true,8,5);Card protect=f.hand("h.HeroicIntervention","Heroic Intervention");UUID a=f.bot.getCommandersIds().iterator().next();Card murder=f.enemyHand("m.Murder","Murder");murder.getSpellAbility().getTargets().get(0).addTarget(a,murder.getSpellAbility(),f.game);f.castEnemy(murder);cast(f,protect,1);drain(f,10);check(f.game.getPermanent(a)!=null,"Reserve denied protection");});
  for(String variant:new String[]{"normal","projected","early","short-hand","short-army","missing-blue","short-mana","unattached","effect-removed","other-commander"})run("Springheart real paid-copy boundary "+variant,()->{Spring s=new Spring(variant);boolean hold=variant.equals("normal")||variant.equals("projected");check(s.f.bot.chooseUse(Outcome.PutCreatureInPlay,"Pay {1}{G} to make a copy?",s.trigger,s.f.game)!=hold,"Wrong optional copy choice");if(hold||variant.equals("early")){s.f.bot.getManaPool().addMana(Mana.GreenMana(2),s.f.game,s.trigger);long w=s.wardens(),insects=s.insects();check(s.trigger.getEffects().get(0).apply(s.f.game,s.trigger),"Real Springheart effect failed");s.f.game.checkStateAndTriggered();check(s.wardens()==w+(hold?0:1)&&s.insects()==insects+(hold?1:0),"Wrong real token alternative");check(s.f.bot.getManaPool().getMana().count()==(hold?2:0),"Wrong optional payment");}});
  run("Natural Springheart landfall drains into mandatory Insects",()->{Spring s=new Spring("normal");Card land=s.f.hand("basiclands.Forest","Forest");long w=s.wardens(),bugs=s.insects();check(s.f.bot.playLand(land,s.f.game,false),"Land failed");s.f.game.checkStateAndTriggered();int n=s.f.game.getStack().size();check(n>0,"No real trigger");drain(s.f,20);check(s.wardens()==w&&s.insects()==bugs+n,"Mandatory Insect alternative changed");});
  finish("RECOVERED_GROWTH");
 }
 static class Spring {
  final FourthSeatRealGameTest.Fixture f;final List<Permanent> wardens=new ArrayList<>();final Card nantuko;final Ability trigger;
  Spring(String v)throws Exception{f=fixture(v.equals("other-commander")?"l.LathrilBladeOfTheElves":"a.AesiTyrantOfGyreStrait",v.equals("other-commander")?"Lathril, Blade of the Elves":"Aesi, Tyrant of Gyre Strait");int count=v.equals("early")?3:4;for(int i=0;i<count;i++)wardens.add(f.board("a.AncientGreenwarden","Ancient Greenwarden"));for(int i=count;i<(v.equals("short-army")?7:8);i++)f.board("g.GrizzlyBears","Grizzly Bears");nantuko=f.hand("s.SpringheartNantuko","Springheart Nantuko");BestowAbility b=(BestowAbility)nantuko.getAbilities().stream().filter(a->a instanceof BestowAbility).findFirst().get().copy();b.getTargets().get(0).addTarget(wardens.get(0).getId(),b,f.game);f.bot.getManaPool().addMana(Mana.GreenMana(2),f.game,b);check(f.bot.activateAbility(b,f.game),"Bestow failed");drain(f,10);check(wardens.get(0).getId().equals(f.game.getPermanent(nantuko.getId()).getAttachedTo()),"Bestow attachment absent");for(int i=0;i<(v.equals("short-mana")?7:8);i++){boolean blue=i<2&&!v.equals("missing-blue");Permanent p=f.board(blue?"basiclands.Island":"basiclands.Forest",blue?"Island":"Forest");if(v.equals("projected"))p.setTapped(true);}for(int i=0;i<(v.equals("short-hand")?7:8);i++)f.hand(i==0?"c.CurseOfTheSwine":i==1?"c.CollectiveResistance":"basiclands.Forest",i==0?"Curse of the Swine":i==1?"Collective Resistance":"Forest");trigger=f.game.getPermanent(nantuko.getId()).getAbilities(f.game).stream().filter(a->a instanceof mage.abilities.common.LandfallAbility).findFirst().get();if(v.equals("unattached")){wardens.get(0).removeAttachment(nantuko.getId(),trigger,f.game);f.game.applyEffects();}if(v.equals("effect-removed")){f.game.addEffect(new mage.abilities.effects.common.continuous.LoseAllAbilitiesTargetEffect(Duration.EndOfTurn).setTargetPointer(new mage.target.targetpointer.FixedTarget(wardens.get(0),f.game)),trigger);f.game.applyEffects();}}
  long wardens(){return f.game.getBattlefield().getAllActivePermanents(f.bot.getId()).stream().filter(p->p.getName().equals("Ancient Greenwarden")).count();}long insects(){return f.game.getBattlefield().getAllActivePermanents(f.bot.getId()).stream().filter(p->p.isToken()&&p.hasSubtype(SubType.INSECT,f.game)&&p.getPower().getValue()==1&&p.getToughness().getValue()==1).count();}
 }
}
